        && \gold.rf_instance.array [1] == \gate.rf_instance.array [1] && \gold.rf_instance.array [1] == 0 
        && \gold.rf_instance.array [2] == \gate.rf_instance.array [2] && \gold.rf_instance.array [2] == 0 
        && \gold.rf_instance.array [3] == \gate.rf_instance.array [3] && \gold.rf_instance.array [3] == 0 
        && \gold.rob_instance.ROB_taken == \gate.rob_instance.ROB_taken && \gold.rob_instance.ROB_taken == 0 
        && \gold.rob_instance.ROB_predicted_taken == \gate.rob_instance.ROB_predicted_taken && \gold.rob_instance.ROB_predicted_taken == 0 
        && \gold.rob_instance.ROB_is_br == \gate.rob_instance.ROB_is_br && \gold.rob_instance.ROB_is_br == 0 
        && \gold.rob_instance.ROB_mem_rdwt == \gate.rob_instance.ROB_mem_rdwt && \gold.rob_instance.ROB_mem_rdwt == 0 
        && \gold.rob_instance.ROB_mem_valid == \gate.rob_instance.ROB_mem_valid && \gold.rob_instance.ROB_mem_valid == 0 
        && \gold.rob_instance.ROB_wen == \gate.rob_instance.ROB_wen && \gold.rob_instance.ROB_wen == 0 
        && \gold.rob_instance.ROB_rd_data_use_execute == \gate.rob_instance.ROB_rd_data_use_execute && \gold.rob_instance.ROB_rd_data_use_execute == 0 
        && \gold.rob_instance.ROB_rs2_stall == \gate.rob_instance.ROB_rs2_stall && \gold.rob_instance.ROB_rs2_stall == 0 
        && \gold.rob_instance.ROB_rs1_stall == \gate.rob_instance.ROB_rs1_stall && \gold.rob_instance.ROB_rs1_stall == 0 
        && \gold.rob_instance.ROB_tail == \gate.rob_instance.ROB_tail && \gold.rob_instance.ROB_tail == 0 
        && \gold.rob_instance.ROB_head == \gate.rob_instance.ROB_head && \gold.rob_instance.ROB_head == 0 
        && \gold.renameTable_instance.renameTB_valid == \gate.renameTable_instance.renameTB_valid && \gold.renameTable_instance.renameTB_valid == 0 
        && \gold.F_pc == \gate.F_pc && \gold.F_pc == 0 
						&& commit_deviation == 0 
						 


						&& gate_stall_signal == gold_stall_signal && gate_stall_signal == 0

						;

		
    wire initialize = (init != 0) || (init_wire) ;

    assume (initialize);

wire gold_invar_0 = \gold.F_opcode == 0 || \gold.F_opcode == 1 || \gold.F_opcode == 2 || \gold.F_opcode == 3 || \gold.F_opcode == 4 || \gold.F_opcode == 5 ;
wire gate_invar_0 = \gate.F_opcode == 0 || \gate.F_opcode == 1 || \gate.F_opcode == 2 || \gate.F_opcode == 3 || \gate.F_opcode == 4 || \gate.F_opcode == 5 ;
assume ( gold_invar_0 && gate_invar_0 ); 

/* ------ Program Assumption ------*/

wire program_0 = \gold.memi_instance.array_mem [0] == \gate.memi_instance.array_mem [0];
wire program_1 = \gold.memi_instance.array_mem [1] == \gate.memi_instance.array_mem [1];
wire program_2 = \gold.memi_instance.array_mem [2] == \gate.memi_instance.array_mem [2];
wire program_3 = \gold.memi_instance.array_mem [3] == \gate.memi_instance.array_mem [3];
wire program_4 = \gold.memi_instance.array_mem [4] == \gate.memi_instance.array_mem [4];
wire program_5 = \gold.memi_instance.array_mem [5] == \gate.memi_instance.array_mem [5];
wire program_6 = \gold.memi_instance.array_mem [6] == \gate.memi_instance.array_mem [6];
wire program_7 = \gold.memi_instance.array_mem [7] == \gate.memi_instance.array_mem [7];

wire program_equiv = program_0 && program_1 && program_2 && program_3 && program_4 && program_5 && program_6 && program_7;
assume (program_equiv);


/* ------ Signals Declaration ------*/

reg gate_stall_signal;
reg gold_stall_signal;
reg commit_deviation;
reg invalid_program;

/* ------ Contract Enforcement ------*/

always @(posedge in_clk) begin 
    if (in_rst ) begin 
        gate_stall_signal <= 0;
        gold_stall_signal <= 0;
        commit_deviation <= 0;
        invalid_program <= 0;
        

    end else begin 
        if (!gold_stall_signal && !gate_stall_signal) begin 

            if (\gate.rob_instance.C_valid && \gold.rob_instance.C_valid ) begin

                        if(\gate.C_is_br == 1 && \gold.C_is_br == 1 &&   \gate.C_taken != \gold.C_taken ) begin
                            invalid_program <= 1;
                        end

            end else if (!\gate.rob_instance.C_valid && \gold.rob_instance.C_valid ) begin 

                        gold_stall_signal <= 1;
                        commit_deviation <= 1;

                        

            end else if (\gate.rob_instance.C_valid && !\gold.rob_instance.C_valid ) begin 

                        gate_stall_signal <= 1;
                        commit_deviation <= 1;
                          
            end

        end else if (gate_stall_signal && !gold_stall_signal ) begin 

            if (\gold.rob_instance.C_valid ) begin 

                    gate_stall_signal <= 0;

                        if(\gate.C_is_br == 1 && \gold.C_is_br == 1 &&   \gate.C_taken != \gold.C_taken ) begin
                            invalid_program <= 1;
                        end

            end

        end else if (!gate_stall_signal && gold_stall_signal ) begin 

            if (\gate.rob_instance.C_valid ) begin 

                    gold_stall_signal <= 0;

                        if(\gate.C_is_br == 1 && \gold.C_is_br == 1 &&   \gate.C_taken != \gold.C_taken ) begin
                            invalid_program <= 1;
                        end

            end

        end
    end
end

assume  (invalid_program == 0 );


    wire trg_equiv = commit_deviation ;

    reg [5: 0]  bound = 30;

    always @ (posedge in_clk) begin
        if (bound > 0 && !state_trg_equiv) begin
            bound <= bound - 1;
        end
    end

    // update the states for verification
    reg state_trg_equiv = 1;
    always @ (posedge in_clk) begin
            state_trg_equiv <= state_trg_equiv && !trg_equiv;
    end

    wire fin_state_trg_equiv = ( bound > 0 || gate_stall_signal || gold_stall_signal) ||  state_trg_equiv ;

    assert  (fin_state_trg_equiv);

endmodule
